## ---------------------------------------------------------------------------
## Toy example #4: fitting a slightly WRONG model to data generated by a
## slightly bigger true one, and watching practical non-identifiability hide
## the mistake.
##
##   TRUE (data-generating) model:  A -> B -> C -> (degraded)   [3 rates: k1,k2,k3]
##   FITTED (wrong) model:          A ->      C -> (degraded)   [2 rates: kAC,k3]
##
## The fitted model is missing the intermediate compartment B entirely -- a
## modeler who didn't know (or chose to ignore) that A converts to C via an
## intermediate. Whether that mistake is visible in the fit depends entirely
## on the TRUE rate constants' timescale separation:
##
##   * If k1 (A->B) and k2 (B->C) are comparable, the true response has a
##     genuinely sigmoidal onset (a delay before C starts rising) that a
##     single A->C step can never reproduce -- the wrong model is cleanly
##     rejected by the data.
##
##   * If k1 >> k2 (A->B fast, B->C rate-limiting), A is consumed and dumped
##     into B on a timescale invisible to the sampling; B then behaves like
##     "fresh starting material" decaying at rate k2. This is exactly the
##     classical quasi-steady-state / rate-limiting-step reduction from
##     chemical kinetics: as k1 -> Infinity, the true model's predicted
##     obsC(t) converges to the wrong model's with kAC = k2 -- the wrong
##     model isn't an approximation, it's the exact k1 -> Infinity limit.
##     In that regime k1 becomes practically non-identifiable: refitting the
##     TRUE 3-rate model to data generated with a large-but-finite k1 makes
##     k1 "slide" off to whatever value the optimizer happens to reach,
##     unconstrained by the data, while k2/k3 stay sharply pinned down. The
##     profile likelihood of k1 is flat (open-ended, "sliding") rather than
##     the parabola expected for a well-identified parameter -- and the
##     structurally wrong (but lower-dimensional) model fits exactly as well
##     as the correct one, because the correct one's extra freedom (k1) buys
##     it nothing the data can see.
##
## This script builds the k1 >> k2 ("hidden mistake") case, fits both
## models, and profiles k1 vs. k2 in the true model to show the flat-vs-sharp
## contrast directly. Part D repeats the fit with k1 and k2 comparable to
## show the mistake becoming visible instead.
##
## Same repo-root/build bootstrap as scripts/example_toy_fit.R; see that file
## for a detailed explanation of the fallback chain below.
## ---------------------------------------------------------------------------

# Locate this script's folder (Rscript or source()); pasting the code into
# a console leaves no file-based signal, so fall back to the fixed path.
# Edit it if this checkout ever moves.
script_dir <- local({
  hit   <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
  ofile <- if (length(sys.frames())) sys.frame(1)$ofile else NULL
  if (length(hit)) dirname(normalizePath(sub("^--file=", "", hit[1])))
  else if (!is.null(ofile)) dirname(normalizePath(ofile))
  else "/home/mio/Phd/2026_dMod_fim-regularization/scripts"
})
source(file.path(script_dir, "setup.R"))

set.seed(11)
setwd(tempdir())

## --- 0. Waterfall diagnostics: condition number at first vs. last step ----
## mstrust_fim() already prints a per-fit "practical identifiability"
## summary at each fit's FIRST evaluation -- singular values of the
## flattened prediction Jacobian d(prediction)/d(parameter) and their
## condition number (max/min) -- see .mstrust_sensitivity_wrapper() in
## R/statistics.R (plain mstrust() does not print this). That's printed
## only, not returned, so it can't be attached to a parframe.
## sensitivityConditionNumber() below recomputes the same number for an
## arbitrary parameter vector, letting us capture it both BEFORE
## optimization (at each fit's starting point) and AFTER (at its converged
## estimate), then use both as waterfall color scales alongside the
## existing iteration-count one from plotValues().
sensitivityConditionNumber <- function(objfun, pars) {
  out <- objfun(pars)
  env <- attr(out, "env")
  prediction <- if (!is.null(env)) env$prediction else NULL
  if (is.null(prediction)) return(NA_real_)
  cn <- vapply(prediction, function(pred) {
    S <- attr(pred, "deriv")
    if (is.null(S)) return(NA_real_)
    J <- S
    dim(J) <- c(dim(S)[1] * dim(S)[2], dim(S)[3])
    sv <- svd(J, nu = 0, nv = 0)$d
    max(sv) / min(sv)
  }, numeric(1))
  max(cn, na.rm = TRUE)
}

## Same layout as plotValues.parframe() (R/parClass.R) -- sorted waterfall,
## vertical dashed lines at tol-detected plateaus -- but colored by an
## arbitrary per-fit numeric vector (aligned to pf's row order) on a log
## color scale, since condition numbers span many orders of magnitude.
## stepDetect() isn't exported; reached via ::: to reuse the exact plateau
## logic plotValues() itself uses rather than duplicating it.
plotWaterfallColored <- function(pf, color_by, color_label, tol = 1) {
  jumps <- stepDetect(pf$value, tol)
  y.range <- c(min(pf$value), max(max(pf$value), min(pf$value) + tol))
  y.jumps <- seq(y.range[2], y.range[1], length.out = length(jumps))

  ord <- order(pf$value)
  pars <- pf[ord, ]
  pars$index <- seq_len(nrow(pars))
  pars$.color <- color_by[ord]

  ggplot2::ggplot(pars, ggplot2::aes(x = index, y = value, pch = converged, color = .color)) +
    ggplot2::geom_vline(xintercept = jumps, lty = 2) +
    ggplot2::geom_point() +
    ggplot2::annotate("text", x = jumps + 1, y = y.jumps, label = jumps, hjust = 0, color = "firebrick", size = 3) +
    ggplot2::xlab("index") + ggplot2::ylab("value") +
    ggplot2::scale_color_gradient(low = "dodgerblue", high = "orange", trans = "log10", name = color_label) +
    ggplot2::coord_cartesian(ylim = y.range) +
    theme_dMod()
}

## The waterfall three ways: colored by iteration count (plotValues()'s own
## default), by the sensitivity condition number at each fit's FIRST
## evaluation (before any optimizer step), and by the same number
## re-evaluated at each fit's FINAL (converged) estimate. Useful when
## plotValues(pf, tol) resolves many closely-spaced plateaus (as with a
## very small tol) and it's not obvious what distinguishes them: does
## plateau membership track how many steps a fit took, how ill-conditioned
## its start was, or how ill-conditioned it ended up?
plotWaterfallDiagnostics <- function(pf, cond_start, cond_end, tol = 1) {
  p_iter  <- plotValues(pf, tol = tol) +
    ggplot2::ggtitle("colored by iterations")
  p_start <- plotWaterfallColored(pf, cond_start, "condition number\n(first step)", tol = tol) +
    ggplot2::ggtitle("colored by sensitivity at first step")
  p_end   <- plotWaterfallColored(pf, cond_end, "condition number\n(last step)", tol = tol) +
    ggplot2::ggtitle("colored by sensitivity at last step")
  cowplot::plot_grid(p_iter, p_start, p_end, nrow = 1)
}

## --- 1. TRUE model: A -> B -> C -> (degraded) -------------------------------
f_true <- NULL
f_true <- addReaction(f_true, from = "A", to = "B", rate = "k1*A", description = "A to B (fast)")
f_true <- addReaction(f_true, from = "B", to = "C", rate = "k2*B", description = "B to C (rate-limiting)")
f_true <- addReaction(f_true, from = "C", to = "",  rate = "k3*C", description = "C degrades")

model_true <- odemodel(f_true, modelname = "toySlideTrueModel")
x_true <- Xs(model_true)
g_true <- Y(eqnvec(obsC = "C"), x_true, compile = TRUE, modelname = "toySlideTrueObs", attachInput = FALSE)

ip_true <- getParameters(g_true * x_true)
trafo_true <- repar(expr = "x~x", x = ip_true)
trafo_true <- repar(trafo_true, "x~0", x = c("B", "C"))   # B(0) = C(0) = 0
trafo_true <- repar(trafo_true, "x~exp(x)", x = ip_true)
p_true <- P(trafo_true, condition = "sim", compile = TRUE, modelname = "toySlideTrueTrafo")

## --- 2. WRONG (fitted) model: A -> C -> (degraded), B skipped entirely -----
f_wrong <- NULL
f_wrong <- addReaction(f_wrong, from = "A", to = "C", rate = "kAC*A", description = "A to C (direct, wrong)")
f_wrong <- addReaction(f_wrong, from = "C", to = "",  rate = "k3*C", description = "C degrades")

model_wrong <- odemodel(f_wrong, modelname = "toySlideWrongModel")
x_wrong <- Xs(model_wrong)
g_wrong <- Y(eqnvec(obsC = "C"), x_wrong, compile = TRUE, modelname = "toySlideWrongObs", attachInput = FALSE)

ip_wrong <- getParameters(g_wrong * x_wrong)
trafo_wrong <- repar(expr = "x~x", x = ip_wrong)
trafo_wrong <- repar(trafo_wrong, "x~0", x = "C")          # C(0) = 0
trafo_wrong <- repar(trafo_wrong, "x~exp(x)", x = ip_wrong)
p_wrong <- P(trafo_wrong, condition = "sim", compile = TRUE, modelname = "toySlideWrongTrafo")

## --- 3. "True" parameters (timescale-separated: k1 >> k2) and simulated data
true_pars <- c(k1 = 3.0, k2 = 0.5, k3 = 0.15, A = 5)
pouter_true <- log(true_pars)

times <- seq(0, 40, by = 6)
prediction_true <- (g_true * x_true * p_true)(times, pouter_true)

sigma <- 0.25
sim <- as.data.frame(prediction_true)
sim$value <- sim$value + rnorm(nrow(sim), sd = sigma)
sim$sigma <- sigma

data <- as.datalist(sim, split.by = "condition")

## --- 4. Fit the WRONG model -------------------------------------------------
obj_wrong <- normL2(data, g_wrong * x_wrong * p_wrong)
init_wrong <- log(c(kAC = 0.5, k3 = 0.2, A = 5)) + rnorm(3, sd = 0.3)

## Precompute the 600 random starting points as a parframe (msParframe(), a
## reproducible-random-starts helper) instead of letting mstrust_fim() sample
## them internally -- passed as `center`, mstrust_fim() then uses each row's
## parameters directly as that fit's parinit (no further randomization; see
## the `is.parframe(center)` branch in mstrust_fim()/R/statistics.R), so
## cond_start_wrong[i], computed from starts_wrong row i BEFORE fitting,
## lines up index-for-index with fit i.
n_fits_wrong <- 600
starts_wrong <- msParframe(init_wrong, n = n_fits_wrong, seed = 21, sd = 0.3)
cond_start_wrong <- vapply(seq_len(n_fits_wrong), function(i)
  sensitivityConditionNumber(obj_wrong, as.parvec(starts_wrong, i)), numeric(1))

fits_wrong <- mstrust_fim(obj_wrong, starts_wrong, name = "toySlideWrongFit", rinit = 1, rmax = 10,
                       cores = 1, iterlim = 300)
pf_wrong <- as.parframe(fits_wrong)
best_wrong <- as.parvec(pf_wrong, 1)

## as.parframe() preserves each row's original 1..n_fits_wrong start slot in
## $index even after sorting by value, so cond_start_wrong[pf_wrong$index]
## still lines up correctly. cond_end is evaluated fresh at each row's own
## converged estimate.
pf_wrong$cond_start <- cond_start_wrong[pf_wrong$index]
pf_wrong$cond_end <- vapply(seq_len(nrow(pf_wrong)), function(j)
  sensitivityConditionNumber(obj_wrong, as.parvec(pf_wrong, j)), numeric(1))

plotValues(pf_wrong, tol=0.00001)
waterfall_diag <- plotWaterfallDiagnostics(pf_wrong, pf_wrong$cond_start, pf_wrong$cond_end, tol = 0.00001)
waterfall_diag


waterfall_diag_path <- file.path(tempdir(), "example_toy_slide_waterfall_diagnostics.png")
ggplot2::ggsave(waterfall_diag_path, waterfall_diag, width = 14, height = 4.5, dpi = 120)
cat("Waterfall diagnostics plot saved to", waterfall_diag_path, "\n")

mytimes <- c(seq(0, max(data$sim$time), 1))

prd <- Reduce("*", list(g_wrong, x_wrong, p_wrong))
plotCombined(prd(mytimes, best_wrong), data)

cat("=== Part A: fitting the WRONG (missing-compartment) model ===\n")
cat("Best objective (wrong model):", pf_wrong$value[1], "\n")
print(exp(best_wrong))

## --- 5. Fit the TRUE model to the SAME data ---------------------------------
## Box-constrain the log-parameters: without a bound, k1 doesn't converge at
## all in any meaningful sense -- the optimizer just drifts along the flat
## direction to whatever huge value it happens to reach (1e14-1e16 in
## earlier runs of this script), which is correct but numerically
## unilluminating. Bounding it to a believable range (k1 up to ~400) turns
## that drift into something you'll recognize from real fits: the estimate
## runs straight to the upper bound instead of settling at an interior
## optimum -- itself a classic tell for practical non-identifiability.
obj_true <- normL2(data, g_true * x_true * p_true)
init_true <- pouter_true + rnorm(4, sd = 0.3)
parupper <- c(k1 = 6, k2 = 4, k3 = 4, A = 4)
parlower <- c(k1 = -4, k2 = -4, k3 = -4, A = -4)

fits_true <- mstrust_fim(obj_true, init_true, name = "toySlideTrueFit", rinit = 1, rmax = 10,
                      fits = 20, cores = 1, iterlim = 300,
                      parupper = parupper, parlower = parlower)
pf_true <- as.parframe(fits_true)
best_true <- as.parvec(pf_true, 1)

cat("\n=== Part B: fitting the TRUE (correct) model to the same data ===\n")
cat("Best objective (true model): ", pf_true$value[1], "\n")
cat("Best objective (wrong model):", pf_wrong$value[1], "\n")
cat("Difference (true - wrong):   ", pf_true$value[1] - pf_wrong$value[1],
    " (near zero -- the extra parameter buys nothing)\n")
print(exp(best_true))
cat("True k1 was", true_pars["k1"], "-- the fit instead runs to the upper bound",
    exp(parupper["k1"]), "\n",
    "(k1 is free to slide arbitrarily high without any fit-quality penalty).\n")
## Once k1 is pinned near-infinity, this 3-state chain still carries the
## same "observed-only-at-the-end" permutation symmetry demonstrated for
## the 10-state chain in example_toy_chain10_fit.R (there among all 10
## rates; here it's the residual 2-fold swap between k2 and k3, with A
## compensating) -- so which one mstrust calls "k2" vs. "k3" isn't
## meaningful, only the pair is. Compare sorted.
fitted_true_inner <- exp(best_true)
cat("k2, k3 sorted, fitted:", sort(fitted_true_inner[c("k2", "k3")]),
    " true:", sort(true_pars[c("k2", "k3")]), "(these ARE identifiable, up to that swap)\n")

## --- 6. Part C: profile likelihood -- k1 slides, k2/k3 don't ---------------
## Same box constraints as the fit above, so the profile can't run off to
## numerically meaningless values either -- it will show k1's objective
## monotonically improving as k1 increases, then plateauing well before the
## bound, in contrast to k2/k3's ordinary parabolic profiles.
cat("\n=== Part C: profile likelihood (k1 vs. k2) ===\n")
prof_k1 <- profile(obj_true, best_true, whichPar = "k1", limits = c(-9, 0.1), method = "optimize",
                    parupper = parupper, parlower = parlower)
prof_k2 <- profile(obj_true, best_true, whichPar = "k2", limits = c(-3, 3), method = "optimize",
                    parupper = parupper, parlower = parlower)
prof_k3 <- profile(obj_true, best_true, whichPar = "k3", limits = c(-3, 3), method = "optimize",
                    parupper = parupper, parlower = parlower)
profs <- do.call(rbind, list(prof_k1, prof_k2, prof_k3))

## The tell isn't the total objective range (all three cover a similar
## span) but the SHAPE: k1's profile keeps improving all the way out to the
## box constraint rather than turning back up around an interior minimum,
## which shows up below as an open (Inf) confidence limit on the side
## facing the constraint. k2/k3 are ordinary parabolas with a minimum
## strictly inside the explored range, so both their limits usually come
## back finite -- though which of k2/k3 draws the open bound on any given
## run depends on which branch of their own residual 2-fold swap symmetry
## (noted above) the optimizer happened to land on. Read the numbers below
## rather than assuming a fixed pattern.
ci <- confint(profs, val.column = "value")
print(ci)
cat("\nk1's non-finite bound reflects genuine, permanent non-identifiability",
    "(runs to the box constraint from any starting point). Any single",
    "non-finite bound on k2/k3 instead reflects THEIR mutual swap symmetry",
    "-- rerun with a different seed and it typically moves to the other one.\n")

pl_prof <- plotProfile(profs)
pl_prof
profile_plot_path <- file.path(tempdir(), "example_toy_slide_profiles.png")
ggplot2::ggsave(profile_plot_path, pl_prof, width = 7, height = 4, dpi = 120)
cat("\nProfile plot saved to", profile_plot_path, "\n")

## --- 7. Part D: same setup, but WITHOUT timescale separation --------------
## Repeat with k1 close to k2 instead of k1 >> k2: now the true response has
## a genuinely sigmoidal onset that a single A->C step cannot mimic, so the
## missing compartment should NOT be hidden by practical non-identifiability
## -- the wrong model should be clearly, visibly worse.
cat("=== Part D: contrast case -- k1 and k2 comparable (mistake NOT hidden) ===\n")
true_pars_d <- c(k1 = 0.6, k2 = 0.7, k3 = 0.15, A = 5)
pred_true_d <- (g_true * x_true * p_true)(times, log(true_pars_d))
sim_d <- as.data.frame(pred_true_d)
sim_d$value <- sim_d$value + rnorm(nrow(sim_d), sd = sigma)
sim_d$sigma <- sigma
data_d <- as.datalist(sim_d, split.by = "condition")

obj_wrong_d <- normL2(data_d, g_wrong * x_wrong * p_wrong)
obj_true_d  <- normL2(data_d, g_true * x_true * p_true)

fits_wrong_d <- mstrust_fim(obj_wrong_d, init_wrong, name = "toySlideWrongFitD", rinit = 1, rmax = 10,
                         fits = 20, cores = 1, iterlim = 300)
fits_true_d  <- mstrust_fim(obj_true_d, log(true_pars_d) + rnorm(4, sd = 0.3), name = "toySlideTrueFitD",
                         rinit = 1, rmax = 10, fits = 20, cores = 1, iterlim = 300)
pf_wrong_d <- as.parframe(fits_wrong_d)
pf_true_d  <- as.parframe(fits_true_d)

cat("Best objective (wrong model):", pf_wrong_d$value[1], "\n")
cat("Best objective (true model): ", pf_true_d$value[1], "\n")
cat("Difference (wrong - true):   ", pf_wrong_d$value[1] - pf_true_d$value[1],
    " (large and positive -- the wrong model is now clearly rejected)\n\n")

## --- 8. Prediction vs. data plot: both fitted models on the hidden case ---
times_fine <- seq(0, 40, by = 0.5)
pred_wrong_fit <- (g_wrong * x_wrong * p_wrong)(times_fine, best_wrong)
pred_true_fit  <- (g_true * x_true * p_true)(times_fine, best_true)

pl <- plot(pred_true_fit, data) +
  ggplot2::geom_line(data = as.data.frame(pred_wrong_fit),
                      ggplot2::aes(time, value), linetype = "dashed", color = "red")
plot_path <- file.path(tempdir(), "example_toy_slide_fit_plot.png")
ggplot2::ggsave(plot_path, pl, width = 7, height = 4, dpi = 120)
cat("Prediction plot saved to", plot_path,
    "(solid = true-model fit, dashed red = wrong-model fit -- expect them to overlap)\n")
